/* Persistent per-film caption storage and word postings. No full-corpus restore. */
globalThis.RetroCaptionIndex=class RetroCaptionIndex{
 constructor(){this.published=typeof RetroPublishedCaptions!=='undefined'?new RetroPublishedCaptions():null;this.published?.ready.catch(e=>{this.publicationError=e.message;});if(typeof BroadcastChannel!=='undefined'){this.updates=new BroadcastChannel('mosh-retrotv-caption-updates');this.updates.onmessage=({data})=>this.onUpdate?.(data);}this.ready=new Promise((resolve,reject)=>{const r=indexedDB.open('mosh-retrotv-captions',1);r.onupgradeneeded=()=>{const db=r.result;db.createObjectStore('docs',{keyPath:'id'});db.createObjectStore('text');db.createObjectStore('terms',{keyPath:['term','id']});db.createObjectStore('state',{keyPath:'id'});};r.onsuccess=()=>resolve(this.db=r.result);r.onerror=()=>reject(r.error);});}
 normalize(s){return s.normalize('NFKC').toLowerCase().replace(/’/g,"'").replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu,'');}
 async get(store,key){await this.ready;return new Promise((resolve,reject)=>{const r=this.db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 async put(id,film){await this.ready;if(await this.get('docs',id))return;await this.counts();
  const groups=new Map();film.words.forEach((w,i)=>{const term=this.normalize(w.text);if(!term)return;if(!groups.has(term))groups.set(term,[]);groups.get(term).push([i,w.start]);});
  const packed={...film,words:film.words.map(w=>[w.start,w.end,w.text])},blob=await new Response(new Blob([JSON.stringify(packed)]).stream().pipeThrough(new CompressionStream('gzip'))).blob();
  await new Promise((resolve,reject)=>{const tx=this.db.transaction(['docs','text','terms','state'],'readwrite');tx.objectStore('docs').put({id,title:film.title,duration:film.duration,words:film.words.length,complete:film.complete!==false,language:film.language});tx.objectStore('text').put(blob,id);for(const [term,positions]of groups)tx.objectStore('terms').put({term,id,positions});this.updateState(tx,{id,status:'captions',words:film.words.length,at:Date.now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});
  const update={id,title:film.title,wordCount:film.words.length};this.updates?.postMessage(update);this.onUpdate?.(update);
 }
 updateState(tx,row){const store=tx.objectStore('state'),old=store.get(row.id);old.onsuccess=()=>{if(old.result?.status==='captions'&&row.status!=='captions')return;const stats=store.get('@counts');stats.onsuccess=()=>{const c=stats.result?.value;if(c){const previous=old.result;if(previous){c[previous.status]=Math.max(0,(c[previous.status]||0)-1);c.words-=previous.words||0;}else c.processed++;c[row.status]=(c[row.status]||0)+1;c.words+=row.words||0;store.put({id:'@counts',value:c});}store.put(row);};};}
 async status(id,status,error,{retryAfterMs=0,httpStatus}={}){await this.ready;await this.counts();const old=await this.get('state',id),attempts=(old?.attempts||0)+1,retryAt=Date.now()+Math.max(retryAfterMs,Math.min(86400000,3600000*2**Math.min(5,attempts-1)));return new Promise((resolve,reject)=>{const tx=this.db.transaction('state','readwrite');this.updateState(tx,{id,status,error,httpStatus,attempts,retryAt,at:Date.now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
 async hasComplete(id){if(this.published){try{await (this.published.available?.()||this.published.ready);if(this.published.docs?.[id]?.complete)return true;}catch{}}return !!(await this.get('docs',id))?.complete;}
 async film(id){if(this.published){await (this.published.available?.()||this.published.ready);if(this.published.docs?.[id])return this.published.film(id);}const blob=await this.get('text',id);if(!blob)return this.published?.film(id);const film=await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).json();film.words=film.words.map(([start,end,text])=>({start,end,text}));return film;}
 async counts(){await this.ready;return new Promise((resolve,reject)=>{const tx=this.db.transaction('state','readwrite'),store=tx.objectStore('state'),r=store.get('@counts');let value;
  r.onsuccess=()=>{const count=store.count();count.onsuccess=()=>{if(r.result&&count.result===r.result.value.processed+1){value=r.result.value;return;}const rows=store.getAll();rows.onsuccess=()=>{value={processed:0,words:0};for(const row of rows.result){if(!row.id.startsWith('yt:'))continue;value.processed++;value[row.status]=(value[row.status]||0)+1;value.words+=row.words||0;}store.put({id:'@counts',value});};};};tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);
 });}
 async localDocuments(){await this.ready;return new Promise((resolve,reject)=>{const r=this.db.transaction('docs').objectStore('docs').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 async localPostings(term){await this.ready;return new Promise((resolve,reject)=>{const r=this.db.transaction('terms').objectStore('terms').getAll(IDBKeyRange.bound([term,''],[term,'\uffff']));r.onsuccess=()=>resolve(new Map(r.result.map(row=>[row.id,row.positions])));r.onerror=()=>reject(r.error);});}
 async documents(){const [local,shared]=await Promise.all([this.localDocuments(),this.published?.documents()||[]]);return [...new Map([...local,...shared].map(d=>[d.id,d])).values()];}
 async postings(term){const [local,shared]=await Promise.all([this.localPostings(term),this.published?.postings(term)||new Map()]);for(const id of local.keys())if(this.published?.docs?.[id])local.delete(id);return new Map([...local,...shared]);}
 async coverage(){const local=await this.counts();if(!this.published)return local;await (this.published.available?.()||this.published.ready);const published=this.published.index?.counts;if(!published)return local;const rows=await new Promise((resolve,reject)=>{const r=this.db.transaction('state').objectStore('state').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});const counts={...published};for(const row of rows){if(!row.id.startsWith('yt:'))continue;const old=this.published.states?.[row.id];if(old?.status==='captions')continue;if(old){counts[old.status]--;counts.words-=old.words||0;}else counts.processed++;counts[row.status]=(counts[row.status]||0)+1;counts.words+=row.words||0;}return counts;}
 async query(word,mode='first',seed=0,accept=()=>true,deferTimes=false){
  const tokens=word.split(/\s+/u).map(t=>this.normalize(t)).filter(Boolean);if(!tokens.length)return {results:[],occurrences:0};
  const [published,lists,documents]=await Promise.all([this.published?.query(word,mode,seed,accept,deferTimes)||{results:[]},Promise.all(tokens.map(t=>this.localPostings(t))),this.localDocuments()]);
  const docs=new Map(documents.map(d=>[d.id,d])),merged=new Map(published.results.map(r=>[r.id,r]));let anchor=0;lists.forEach((l,i)=>{if(l.size<lists[anchor].size)anchor=i});
  for(const [id,positions]of lists[anchor]){
   if(this.published?.docs?.[id]||!accept(id)||lists.some(l=>!l.has(id)))continue;
   let hash=seed|0;for(const ch of id)hash=Math.imul(hash^ch.charCodeAt(0),16777619);
   let index,start,matches;
   if(tokens.length===1){const hit=positions[mode==='random'?(hash>>>0)%positions.length:0];[index,start]=hit;matches=positions.length;}
   else{const sets=lists.map(l=>new Set(l.get(id).map(p=>p[0]))),times=new Map(lists[0].get(id));const hits=positions.map(p=>p[0]-anchor).filter(p=>tokens.every((_,i)=>sets[i].has(p+i)));if(!hits.length)continue;index=hits[mode==='random'?(hash>>>0)%hits.length:0];start=times.get(index);matches=hits.length;}
   merged.set(id,{id,title:docs.get(id).title,index,start,matches,context:'',batch:true});
  }
  const results=[...merged.values()];return {results,occurrences:results.reduce((n,r)=>n+r.matches,0)};
 }
};
